#include <stdio.h>

int main(void) {
    int N;
    long long S;

    if (scanf("%d", &N) != 1) return 0;
    scanf("%lld", &S);

    int X[100000];
    for (int i = 0; i < N; i++) {
        scanf("%d", &X[i]);
    }

    long long count_at_most_S = 0;
    long long count_at_most_S_minus_1 = 0;

    int left = 0;
    long long sum = 0;
    for (int right = 0; right < N; right++) {
        sum += X[right];
        while (sum > S) {
            sum -= X[left++];
        }
        count_at_most_S += right - left + 1;
    }

    if (S > 0) {
        left = 0;
        sum = 0;
        for (int right = 0; right < N; right++) {
            sum += X[right];
            while (sum > S - 1) {
                sum -= X[left++];
            }
            count_at_most_S_minus_1 += right - left + 1;
        }
    }

    printf("%lld\n", count_at_most_S - count_at_most_S_minus_1);
    return 0;
}
